def control_plane() -> dict[str, tuple[str, str]]:
    """The `kube-apiserver` and `etcd` images the pinned Talos release runs by default: by name, repository and tag."""
    talosctl = pinned_tools.located('talosctl')
    images = process_sessions.run([talosctl, 'images', 'default'], text=True, timeout=COMMAND_TIMEOUT, check=True)
    found = {match[2]: (match[1], match[3]) for match in CONTROL_PLANE.finditer(images.stdout)}
    assert set(found) == {'kube-apiserver', 'etcd'}, images.stdout
    return found

